frappe.ui.form.on("Delivery Note", {
	validate: function(frm) {
		let primary_wh = null;
		for (let row of (frm.doc.items || [])) {
			if (row.warehouse) {
				if (!primary_wh) {
					primary_wh = row.warehouse;
				} else if (row.warehouse !== primary_wh) {
					frappe.msgprint({
						title: __("Multiple Warehouses Not Allowed"),
						indicator: "red",
						message: __("A Delivery Note should be confined to a single warehouse only (<b>{0}</b>). Row #{1} ({2}) has warehouse '<b>{3}</b>'. Please select <b>{0}</b> or create a separate Delivery Note for other warehouses.", [primary_wh, row.idx, row.item_code || row.item_name || "", row.warehouse])
					});
					frappe.validated = false;
					return false;
				}
			}
		}
	},
	setup: function(frm) {
		// Set dynamic address queries filtered by Transporter
		frm.set_query("transporter", function() {
			return { filters: { is_transporter: 1 } };
		});

		frm.set_query("custom_transporter_from_address", function() {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.transporter || ""
				}
			};
		});

				frm.set_query("shipping_contact_person", function() {
			return {
				query: "frappe.contacts.doctype.contact.contact.contact_query",
				filters: { link_doctype: "Customer", link_name: frm.doc.customer || "" }
			};
		});

frm.set_query("custom_transporter_to_address", function() {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.transporter || ""
				}
			};
		});
	},

	onload: function(frm) {
		if (frm.doc.company == "Sravi Enterprises - Kolapakkam" && !frm.doc.set_warehouse) {
			frm.set_value("set_warehouse", "Stores - SE-K");
		}
	},

	refresh: function(frm) {
		if (frm.is_new()) {
			return;
		}

		// Hide default 'Create > Packing Slip' button to avoid duplication with our custom Packing Slips group
		frm.page.remove_inner_button(__("Packing Slip"), __("Create"));

		// Hide default 'Create > Packing Slip' button to avoid duplication with our custom Packing Slips group
		frm.page.remove_inner_button(__("Packing Slip"), __("Create"));

		// 1. Logistics Button Group
		frm.page.add_inner_button(__("Transporter"), function() {
			open_transporter_dialog(frm);
		}, __("Logistics"));

		frm.page.add_inner_button(__("Update LR Details"), function() {
			open_lr_dialog(frm);
		}, __("Logistics"));

		// 2. Packing Slips Button Group
		frm.page.add_inner_button(__("Generate"), function() {
			open_packing_slip_generator(frm);
		}, __("Packing Slips"));

		frm.page.add_inner_button(__("Manage / Edit"), function() {
			open_manage_packing_slips_dialog(frm);
		}, __("Packing Slips"));

	},

customer: function(frm) {
		setTimeout(function() {
			if (frm.doc.customer && !frm.doc.shipping_contact_person) {
				let cp = frm.doc.contact_person;
				if (cp) {
					frm.set_value("shipping_contact_person", cp);
				}
			}
		}, 500);
	},

	contact_person: function(frm) {
		if (frm.doc.contact_person && !frm.doc.shipping_contact_person) {
			frm.set_value("shipping_contact_person", frm.doc.contact_person);
		}
	},

	shipping_address_name: function(frm) {
		if (frm.doc.shipping_address_name && !frm.doc.shipping_contact_person && frm.doc.contact_person) {
			frm.set_value("shipping_contact_person", frm.doc.contact_person);
		}
	},

	shipping_contact_person: function(frm) {
		if (frm.doc.shipping_contact_person) {
			frappe.call({
				method: "frappe.contacts.doctype.contact.contact.get_contact_details",
				args: { contact: frm.doc.shipping_contact_person },
				callback: function(r) {
					if (r.message) {
						frm.set_value("shipping_contact_display", r.message.contact_display || frm.doc.shipping_contact_person);
						frm.set_value("shipping_contact_mobile", r.message.contact_mobile || r.message.contact_phone || "");
						frm.set_value("shipping_contact_email", r.message.contact_email || "");
					}
				}
			});
		} else {
			frm.set_value("shipping_contact_display", "");
			frm.set_value("shipping_contact_mobile", "");
			frm.set_value("shipping_contact_email", "");
		}
	},

	transporter: function(frm) {
		if (!frm.doc.transporter) {
			frm.set_value("transporter_name", "");
			frm.set_value("custom_transporter_from_address", "");
			frm.set_value("custom_transporter_from_address_display", "");
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},

	custom_transporter_from_address: function(frm) {
		if (frm.doc.custom_transporter_from_address) {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_address_display",
				args: { address_dict: frm.doc.custom_transporter_from_address },
				callback: function(res) {
					let raw_html = res.message || "";
					let clean_text = raw_html.replace(/<br\s*[/]?>/gi, "\n").replace(/<[^>]+>/g, "").trim();
					frm.set_value("custom_transporter_from_address_display", clean_text);
				}
			});
		} else {
			frm.set_value("custom_transporter_from_address_display", "");
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},

	custom_is_godown_delivery: function(frm) {
		if (!frm.doc.custom_is_godown_delivery) {
			frm.set_value("custom_transporter_to_address", "");
			frm.set_value("custom_transporter_to_address_display", "");
		}
	},

	custom_transporter_to_address: function(frm) {
		if (frm.doc.custom_transporter_to_address) {
			frappe.call({
				method: "frappe.contacts.doctype.address.address.get_address_display",
				args: { address_dict: frm.doc.custom_transporter_to_address },
				callback: function(res) {
					let raw_html = res.message || "";
					let clean_text = raw_html.replace(/<br\s*[/]?>/gi, "\n").replace(/<[^>]+>/g, "").trim();
					frm.set_value("custom_transporter_to_address_display", clean_text);
				}
			});
		} else {
			frm.set_value("custom_transporter_to_address_display", "");
		}
	}
});

// ==========================================
// 1. Transporter Assignment & Edit Dialog
// ==========================================
function open_transporter_dialog(frm) {
	frappe.call({
		method: "core_customizations.core_customizations.delivery_note.get_unpacked_items_summary",
		args: { delivery_note: frm.doc.name },
		freeze: true,
		callback: function(r) {
			if (!r.message) return;
			let data = r.message;
			let current = data.current_transporter || {};
			let defaults = data.customer_defaults || {};

			let has_saved_logistics = !!(current.transporter && current.from_address);
			let init_transporter = has_saved_logistics ? (current.transporter || "") : "";
			let init_from_addr = has_saved_logistics ? (current.from_address || "") : "";
			let init_is_godown = has_saved_logistics ? (current.is_godown_delivery || 0) : 0;
			let init_to_addr = has_saved_logistics ? (current.to_address || "") : "";

			let is_initializing = true;
			let last_transporter = init_transporter;

			function load_customer_defaults() {
				if (!defaults.default_transporter) {
					frappe.msgprint(__("No default transporter configured for Customer <b>{0}</b>.", [frm.doc.customer || ""]));
					return;
				}
				is_initializing = true;
				last_transporter = defaults.default_transporter;
				update_address_queries(defaults.default_transporter);
				d.set_values({
					transporter: defaults.default_transporter,
					from_address: defaults.default_from_address || "",
					is_godown_delivery: defaults.default_is_godown || 0,
					to_address: defaults.default_is_godown ? (defaults.default_to_address || "") : ""
				});
				d.set_df_property("is_godown_delivery", "hidden", !defaults.default_from_address);
				d.set_df_property("to_address", "hidden", !defaults.default_is_godown);
				d.set_df_property("to_address", "reqd", !(!defaults.default_is_godown));
				d.set_df_property("to_address_html", "hidden", !defaults.default_is_godown);
				if (defaults.default_from_address) {
					update_address_preview("from_address", "from_address_html", d, false);
				}
				if (defaults.default_is_godown && defaults.default_to_address) {
					update_address_preview("to_address", "to_address_html", d, true);
				}
				is_initializing = false;
				frappe.show_alert({ message: __("Customer transporter defaults loaded"), indicator: "blue" });
			}

			let d = new frappe.ui.Dialog({
				title: __("Assign Transporter & Logistics Details"),
				fields: [
					{
						fieldtype: "Button",
						fieldname: "fetch_defaults_btn",
						label: __("🔄 Fetch Customer Defaults"),
						click: function() {
							load_customer_defaults();
						}
					},
					{
						fieldtype: "Link",
						fieldname: "transporter",
						label: __("Transporter"),
						options: "Supplier",
						get_query: function() {
							return { filters: { is_transporter: 1 } };
						},
						onchange: function() {
							if (is_initializing) return;
							let t = d.get_value("transporter");
							if (t === last_transporter) return;
							last_transporter = t;

							update_address_queries(t);

							d.set_value("from_address", "");
							d.set_value("is_godown_delivery", 0);
							d.set_value("to_address", "");
							d.set_df_property("is_godown_delivery", "hidden", 1);
							d.set_df_property("to_address", "hidden", 1);
							d.set_df_property("to_address_html", "hidden", 1);
							d.fields_dict.from_address_html.$wrapper.html("");
							d.fields_dict.to_address_html.$wrapper.html("");
						}
					},
					{
						fieldtype: "Link",
						fieldname: "from_address",
						label: __("Origin / Booking Hub Address"),
						options: "Address",
						onchange: function() {
							let f = d.get_value("from_address");
							update_address_preview("from_address", "from_address_html", d, false);
							if (f) {
								d.set_df_property("is_godown_delivery", "hidden", 0);
							} else {
								d.set_df_property("is_godown_delivery", "hidden", 1);
								if (!is_initializing) {
									d.set_value("is_godown_delivery", 0);
									d.set_value("to_address", "");
									d.fields_dict.to_address_html.$wrapper.html("");
								}
							}
						}
					},
					{
						fieldtype: "HTML",
						fieldname: "from_address_html"
					},
					{
						fieldtype: "Check",
						fieldname: "is_godown_delivery",
						label: __("Is Godown Delivery"),
						onchange: function() {
							let is_g = d.get_value("is_godown_delivery");
							d.set_df_property("to_address", "hidden", !is_g);
							d.set_df_property("to_address", "reqd", !(!is_g));
							d.set_df_property("to_address_html", "hidden", !is_g);
							if (is_g) {
								update_address_preview("to_address", "to_address_html", d, true);
							} else {
								if (!is_initializing) {
									d.set_value("to_address", "");
									d.fields_dict.to_address_html.$wrapper.html("");
								}
							}
						}
					},
					{
						fieldtype: "Link",
						fieldname: "to_address",
						label: __("Destination Godown Address"),
						options: "Address",
						onchange: function() {
							update_address_preview("to_address", "to_address_html", d, true);
						}
					},
					{
						fieldtype: "HTML",
						fieldname: "to_address_html"
					}
				],
				primary_action_label: __("Save Transporter Details"),
				secondary_action_label: __("Fetch Defaults"),
				secondary_action: function() {
					load_customer_defaults();
				},
				primary_action: function(values) {
					if (values.is_godown_delivery && !values.to_address) {
						frappe.msgprint(__("Destination Godown Address is mandatory when Godown Delivery is selected."));
						return;
					}

					frappe.call({
						method: "core_customizations.core_customizations.delivery_note.update_transporter_details",
						args: {
							delivery_note: frm.doc.name,
							transporter: values.transporter,
							from_address: values.from_address,
							is_godown: values.is_godown_delivery ? 1 : 0,
							to_address: values.is_godown_delivery ? values.to_address : null
						},
						freeze: true,
						callback: function(res) {
							d.hide();
							frm.reload_doc();
							frappe.show_alert({ message: __("Transporter details updated successfully"), indicator: "green" });
						}
					});
				}
			});

			function update_address_queries(transporter_name) {
				d.set_df_property("from_address", "get_query", function() {
					return {
						query: "frappe.contacts.doctype.address.address.address_query",
						filters: { link_doctype: "Supplier", link_name: transporter_name || "" }
					};
				});
				d.set_df_property("to_address", "get_query", function() {
					return {
						query: "frappe.contacts.doctype.address.address.address_query",
						filters: { link_doctype: "Supplier", link_name: transporter_name || "" }
					};
				});
			}

			// 1. Set dynamic address queries based on initial transporter
			update_address_queries(init_transporter);

			// 2. Set field values explicitly
			d.set_values({
				transporter: init_transporter,
				from_address: init_from_addr,
				is_godown_delivery: init_is_godown,
				to_address: init_to_addr
			});

			// 3. Set visibility properties based on initial values
			d.set_df_property("is_godown_delivery", "hidden", !init_from_addr);
			d.set_df_property("to_address", "hidden", !init_is_godown);
			d.set_df_property("to_address", "reqd", !(!init_is_godown));
			d.set_df_property("to_address_html", "hidden", !init_is_godown);

			// 4. Render initial address previews
			if (init_from_addr) {
				update_address_preview("from_address", "from_address_html", d, false);
			}
			if (init_is_godown && init_to_addr) {
				update_address_preview("to_address", "to_address_html", d, true);
			}

			d.show();
			is_initializing = false;
		}
	});
}

function update_address_preview(fieldname, html_fieldname, d, is_destination) {
	let addr_name = d.get_value(fieldname);
	if (!addr_name) {
		d.fields_dict[html_fieldname].$wrapper.html("");
		return;
	}

	frappe.call({
		method: "frappe.contacts.doctype.address.address.get_address_display",
		args: { address_dict: addr_name },
		callback: function(res) {
			let raw_html = res.message || "";
			let display = raw_html.replace(/<br\s*[/]?>/gi, ", ").replace(/<[^>]+>/g, "").replace(/\n+/g, ", ").trim();
			if (display) {
				let border_style = is_destination ? "border: 1.5px dashed #c53030; background-color: #fff5f5;" : "border: 1px solid #cbd5e0; background-color: #f7fafc;";
				let title = is_destination ? "📍 <b>Destination Godown:</b>" : "🏢 <b>Origin / Booking Hub:</b>";
				d.fields_dict[html_fieldname].$wrapper.html(`
					<div style="${border_style} border-radius: 4px; padding: 6px 10px; margin-top: 4px; margin-bottom: 6px; font-size: 12px; line-height: 1.4; color: #2d3748;">
						${title} ${display}
					</div>
				`);
			} else {
				d.fields_dict[html_fieldname].$wrapper.html("");
			}
		}
	});
}

