			if (!r.message || r.message.length === 0) {
				frappe.msgprint(__("No Packing Slips found for this Delivery Note."));
				return;
			}
			let draft_slips = r.message.filter(s => s.docstatus === 0);
			if (draft_slips.length === 0) {
				frappe.msgprint(__("All Packing Slips for this Delivery Note are already submitted."));
				return;
			}

			let d = new frappe.ui.Dialog({
				title: __("Submit Draft Packing Slips ({0} Draft Boxes)", [draft_slips.length]),
				fields: [
					{
						fieldtype: "HTML",
						fieldname: "submit_table_html"
					}
				],
				primary_action_label: __("Submit Selected Slips"),
				primary_action: function() {
					let selected = [];
					d.$wrapper.find(".select-draft-ps:checked").each(function() {
						selected.push($(this).attr("data-ps"));
					});

					if (selected.length === 0) {
						frappe.msgprint(__("Please select at least one Packing Slip to submit."));
						return;
					}

					frappe.call({
						method: "core_customizations.core_customizations.delivery_note.submit_packing_slips",
						args: {
							delivery_note: frm.doc.name,
							packing_slip_names: JSON.stringify(selected)
						},
						freeze: true,
						callback: function(res) {
							d.hide();
							frm.reload_doc();
							frappe.show_alert({ message: res.message.message, indicator: "green" });
						}
					});
				}
			});

			let html = `
				<div style="max-height: 400px; overflow-y: auto;">
					<table class="table table-bordered table-sm" style="font-size: 12px; margin-bottom: 0;">
						<thead>
							<tr style="background-color: #f8f9fa;">
								<th style="width: 35px; text-align: center;">
									<input type="checkbox" id="select-all-draft-ps" checked>
								</th>
								<th style="width: 80px; text-align: center;">${__("Box No")}</th>
								<th style="width: 140px;">${__("Packing Slip")}</th>
								<th>${__("Packed Items")}</th>
								<th style="width: 85px; text-align: center;">${__("Action")}</th>
							</tr>
					</thead>
					<tbody>
			`;

			draft_slips.forEach(function(s) {
				html += `
					<tr>
						<td style="text-align: center; vertical-align: middle;">
							<input type="checkbox" class="select-draft-ps" data-ps="${s.name}" checked>
						</td>
						<td style="font-weight: bold; text-align: center; vertical-align: middle;">Box ${s.box_no}</td>
						<td style="vertical-align: middle;"><a href="/app/packing-slip/${s.name}" target="_blank"><b>${s.name}</b></a></td>
						<td style="vertical-align: middle;">${s.items_display}</td>
						<td style="text-align: center; vertical-align: middle;">
							<button class="btn btn-xs btn-primary submit-single-ps-row" data-ps="${s.name}">
								<i class="fa fa-check"></i> ${__("Submit")}
							</button>
						</td>
					</tr>
				`;
			});

			html += `</tbody></table></div>`;
			d.fields_dict.submit_table_html.$wrapper.html(html);

			// Master checkbox toggle
			d.$wrapper.on("change", "#select-all-draft-ps", function() {
				let is_checked = $(this).is(":checked");
				d.$wrapper.find(".select-draft-ps").prop("checked", is_checked);
			});

			// Individual submit button handler
			d.$wrapper.on("click", ".submit-single-ps-row", function() {
				let ps_name = $(this).attr("data-ps");
				frappe.call({
					method: "core_customizations.core_customizations.delivery_note.submit_packing_slips",
					args: {
						delivery_note: frm.doc.name,
						packing_slip_names: JSON.stringify([ps_name])
					},
					freeze: true,
					callback: function(res) {
						d.hide();
						frm.reload_doc();
						frappe.show_alert({ message: res.message.message, indicator: "green" });
					}
				});
			});

			d.show();
		}
	});
}

