// ==========================================
// Delivery Note Item: Single Warehouse Confinement
// ==========================================
frappe.ui.form.on("Delivery Note Item", {
	warehouse: function(frm, cdt, cdn) {
		let row = locals[cdt][cdn];
		if (!row.warehouse) return;

		// Find the first warehouse configured on any other item row
		let primary_wh = null;
		for (let item of (frm.doc.items || [])) {
			if (item.name !== row.name && item.warehouse) {
				primary_wh = item.warehouse;
				break;
			}
		}

		if (primary_wh && row.warehouse !== primary_wh) {
			let invalid_wh = row.warehouse;
			// Revert to primary_wh
			frappe.model.set_value(cdt, cdn, "warehouse", primary_wh);
			frappe.msgprint({
				title: __("Single Warehouse Confinement"),
				indicator: "orange",
				message: __("A Delivery Note should be confined to a single warehouse only.<br><br>The first item configured warehouse is <b>{0}</b>. Resetting Row #{1} from <b>{2}</b> back to <b>{0}</b>.<br><br>If items are to be dispatched from different warehouses, please create separate Delivery Notes.", [primary_wh, row.idx, invalid_wh])
			});
		}
	},

	items_add: function(frm, cdt, cdn) {
		let primary_wh = null;
		for (let item of (frm.doc.items || [])) {
			if (item.warehouse) {
				primary_wh = item.warehouse;
				break;
			}
		}
		if (primary_wh) {
			frappe.model.set_value(cdt, cdn, "warehouse", primary_wh);
		}
	}
});

