		frm.set_query("custom_default_transporter_from_address", function() {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_default_transporter || ""
				}
			};
		});

		frm.set_query("custom_default_transporter_to_address", function() {
			return {
				query: "frappe.contacts.doctype.address.address.address_query",
				filters: {
					link_doctype: "Supplier",
					link_name: frm.doc.custom_default_transporter || ""
				}
			};
		});
	},

	custom_default_transporter: function(frm) {
		if (!frm.doc.custom_default_transporter) {
			frm.set_value("custom_default_transporter_from_address", "");
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_default_transporter_to_address", "");
		}
	},

	custom_default_transporter_from_address: function(frm) {
		if (!frm.doc.custom_default_transporter_from_address) {
			frm.set_value("custom_is_godown_delivery", 0);
			frm.set_value("custom_default_transporter_to_address", "");
		}
	},

	custom_is_godown_delivery: function(frm) {
		if (!frm.doc.custom_is_godown_delivery) {
			frm.set_value("custom_default_transporter_to_address", "");
		}
	}
});

